	Comment string

	// Type 是 SMB2 ShareType。磁盘共享为 DISK，IPC$ 为 PIPE。
	Type wire.ShareType

	// FS 是后端文件系统。IPC$ 没有文件系统，此处为 nil。
	FS vfs.FileSystem

	// ReadOnly 只读共享。
	ReadOnly bool
	// GuestOK 允许 guest 身份访问。
	GuestOK bool
	// Browseable 控制是否出现在共享枚举中。
