 164→// handleSMB1 处理 SMB1 多协议协商入口（protocol-notes §4）。
 165→func (c *Connection) handleSMB1(frame []byte) ([]byte, error) {
 166→	if c.state.NegotiateDone {
 167→		// 协商完成后再收到 SMB1 是异常，直接断连。
 168→		return nil, errSMB1Refused
 169→	}
 170→	if !c.srv.opts.Settings.AllowSMB1Negotiate {
 171→		return nil, fmt.Errorf("%w: SMB1 协商入口已禁用", errSMB1Refused)
 172→	}
 173→
 174→	dialects, err := command.ParseSMB1NegotiateDialects(frame)
 175→	if err != nil {
 176→		return nil, fmt.Errorf("%w: %v", errSMB1Refused, err)
 177→	}
 178→
 179→	out, err := command.AppendSMB1NegotiateReply(c.state, dialects, nil)
 180→	if err != nil {
 181→		return nil, fmt.Errorf("%w: %v", errSMB1Refused, err)
 182→	}
 183→	c.log.Debug("以 SMB2 应答 SMB1 多协议协商", "dialects", dialects)
 184→	return out, nil
 185→}
