 187→// respMsg 记录复合响应链中一条消息的位置与后处理需求。
 188→type respMsg struct {
 189→	start int
 190→	// signKey 非 nil 时要对本条响应签名（范围含尾部对齐填充）。
 191→	signKey []byte
 192→	// hashConn / hashSession 是 3.1.1 preauth integrity hash 的更新目标。
 193→	hashConn    bool
 194→	hashSession *command.Session
 195→}
 196→
 197→// handleSMB2Chain 处理一个 SMB2 帧（可能是复合请求链）。
 198→//
 199→// MS-SMB2 §3.3.5.2.7 / protocol-notes §2：
 200→//   - NextCommand != 0 时本条消息长度即 NextCommand，== 0 时延伸到帧尾；
 201→//   - 每段起点 8 字节对齐；
 202→//   - 响应也必须拼成复合链一次性提交给传输层。
 203→func (c *Connection) handleSMB2Chain(frame []byte) ([]byte, error) {
 204→	chain := &command.Chain{}
 205→	var out []byte
 206→	var msgs []respMsg
 207→
 208→	pos := 0
 209→	for {
 210→		seg := frame[pos:]
 211→		hdr, err := wire.ParseHeader(seg)
 212→		if err != nil {
 213→			return nil, fmt.Errorf("%w: %v", errBadCompound, err)
 214→		}
 215→
 216→		segLen := len(seg)
 217→		if hdr.NextCommand != 0 {
 218→			segLen = int(hdr.NextCommand)
 219→			// NextCommand 必须至少覆盖一个头，且不能越出本帧。
 220→			if segLen < wire.HeaderSize || segLen > len(seg) {
 221→				return nil, fmt.Errorf("%w: NextCommand=%d 超界（剩余 %d）",
 222→					errBadCompound, hdr.NextCommand, len(seg))
 223→			}
 224→		}
 225→		msg := seg[:segLen]
 226→
 227→		// 拼接上一条响应：先补 8 字节对齐，再回填它的 NextCommand。
 228→		if len(msgs) > 0 {
 229→			out = pad8(out)
 230→			prev := msgs[len(msgs)-1].start
 231→			setNextCommand(out, prev, uint32(len(out)-prev))
 232→		}
 233→
 234→		ctx := c.processMessage(hdr, msg, chain, out)
 235→		out = ctx.Out
 236→		msgs = append(msgs, respMsg{
 237→			start:       ctx.MsgStart(),
 238→			signKey:     ctx.SignKey,
 239→			hashConn:    ctx.HashResponseConn,
 240→			hashSession: ctx.HashResponseSession,
 241→		})
 242→
 243→		if hdr.NextCommand == 0 {
 244→			break
 245→		}
 246→		pos += segLen
 247→		if pos >= len(frame) {
 248→			// NextCommand 指到了帧尾之外。
 249→			return nil, fmt.Errorf("%w: 链在偏移 %d 处越界", errBadCompound, pos)
 250→		}
 251→	}
 252→
 253→	c.finishChain(out, msgs)
 254→	return out, nil
 255→}
 256→
 257→// finishChain 在复合链拼装完成后执行 preauth hash 更新与签名。
 258→//
 259→// 顺序很重要：
 260→//  1. 此时 NextCommand 与对齐填充都已就位，字节内容不会再变；
 261→//  2. preauth hash 覆盖的是**未签名**的响应（3.1.1 中间轮次的 SESSION_SETUP
 262→//     响应不签名，最终成功的响应签名但不参与 hash，两者不冲突）；
 263→//  3. 签名范围**含尾部对齐填充字节**（protocol-notes §2，极易踩坑）。
 264→func (c *Connection) finishChain(out []byte, msgs []respMsg) {
 265→	for i, m := range msgs {
 266→		end := len(out)
 267→		if i+1 < len(msgs) {
 268→			end = msgs[i+1].start
 269→		}
 270→		seg := out[m.start:end]
 271→
 272→		if m.hashConn {
 273→			c.state.UpdatePreauthHash(seg)
 274→		}
 275→		if m.hashSession != nil {
 276→			m.hashSession.UpdatePreauthHash(seg)
 277→		}
 278→		if len(m.signKey) > 0 {
 279→			if err := crypto.SignWith(c.state.SigningAlg(), m.signKey, seg); err != nil {
 280→				c.log.Error("响应签名失败", "err", err)
 281→			}
 282→		}
 283→	}
 284→}
 285→
 286→// processMessage 处理复合链中的一条消息，把响应追加到 out。
 287→func (c *Connection) processMessage(hdr wire.Header, msg []byte,
 288→	chain *command.Chain, out []byte) *command.Context {
 289→
 290→	ctx := command.NewContext(c.state, chain, hdr, msg, out)
 291→
 292→	// —— credit 记账（protocol-notes §12）——
 293→	// 任何响应都至少授予 1 个 credit，否则客户端会停止发送并挂死。
 294→	c.credits.SetMultiCredit(c.state.SupportsMultiCredit())
 295→	charge := c.credits.Charge(hdr.CreditCharge)
 296→	ctx.SetCredits(c.credits.Grant(charge, hdr.Credits))
 297→
 298→	// 会话/树定位与签名校验都在 command.Dispatch 内完成
 299→	// （它需要在同一处决定响应是否签名）。
 300→	command.Dispatch(ctx)
 301→	return ctx
 302→}
 303→
 304→// pad8 把 dst 补齐到 8 字节对齐（复合响应链要求，MS-SMB2 §3.3.5.2.7）。
 305→func pad8(dst []byte) []byte {
 306→	if n := (8 - len(dst)%8) % 8; n > 0 {
 307→		dst = append(dst, make([]byte, n)...)
 308→	}
 309→	return dst
 310→}
 311→
 312→// setNextCommand 回填 buf 中位于 start 处的 SMB2 头的 NextCommand 字段
 313→// （偏移 0x14，4 字节**小端**）。
 314→func setNextCommand(buf []byte, start int, v uint32) {
 315→	off := start + 0x14
 316→	if off+4 > len(buf) {
 317→		return
 318→	}
 319→	buf[off+0] = byte(v)
 320→	buf[off+1] = byte(v >> 8)
 321→	buf[off+2] = byte(v >> 16)
 322→	buf[off+3] = byte(v >> 24)
 323→}
