// NextEncryptNonce 返回下一个 S2C 加密 nonce（单调递增，绝不重复）。
//
// 同一 (密钥, 方向) 下 nonce 复用会直接泄露明文异或值（SMB3 CCM/GCM），
// 因此必须在锁内推进计数器，禁止随机或重置。
func (s *Session) NextEncryptNonce() [16]byte {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.encNonce == nil {
		s.encNonce = &crypto.NonceCounter{}
	}
	return s.encNonce.Next()
}"}

