		t.Fatalf("Pack: %v", err)
	}
	got, err := Unpack(raw)
	if err != nil {
		t.Fatalf("Unpack: %v", err)
	}
	if len(got.Answers) != 1 {
		t.Fatalf("解出 %d 条记录, 期望 1", len(got.Answers))
	}
	rec, ok := got.Answers[0].Data.(TXT)
	if !ok {
		t.Fatalf("记录类型 = %T, 期望 TXT", got.Answers[0].Data)
	}
	if !reflect.DeepEqual(rec.Strings, def.TXT) {
